insert into public.lessons (course_id, unit_id, slug, n, title, reference, minutes, verse_ref, verse_text, quiz_count) values
  ('john', (select id from public.units where course_id = 'john' and position = 1), '0001-how-to-study-scripture.html', 1, 'How to Study Scripture', '', 25, 'John 20:30-31, ESV', 'Now Jesus did many other signs in the presence of the disciples, which are not written in this book; but these are written so that you may believe that Jesus is the Christ, the Son of God, and that by believing you may have life in his name.', 4),
  ('john', (select id from public.units where course_id = 'john' and position = 1), '0002-john-big-picture.html', 2, 'The Big Picture of John', '', 25, 'John 20:31, ESV', '...but these are written so that you may believe that Jesus is the Christ, the Son of God, and that by believing you may have life in his name.', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 2), '0003-john-1-1-18-the-word-made-flesh.html', 3, 'The Word Made Flesh', 'John 1:1-18', 30, 'John 1:1, ESV', 'In the beginning was the Word, and the Word was with God, and the Word was God.', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 2), '0004-john-1-19-34-behold-the-lamb.html', 4, 'Behold the Lamb', 'John 1:19-34', 25, 'John 1:29, ESV', 'The next day he saw Jesus coming toward him, and said, "Behold, the Lamb of God, who takes away the sin of the world!"', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 2), '0005-john-1-35-51-come-and-see.html', 5, 'Come and See', 'John 1:35-51', 25, 'John 1:49, ESV', 'Nathanael answered him, "Rabbi, you are the Son of God! You are the King of Israel!"', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 2), '0006-john-2-1-12-water-into-wine.html', 6, 'Water into Wine', 'John 2:1-12', 25, 'John 2:4, ESV', 'And Jesus said to her, "Woman, what does this have to do with me? My hour has not yet come."', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 2), '0007-john-2-13-25-zeal-for-your-house.html', 7, 'Zeal for Your House', 'John 2:13-25', 25, 'John 2:19, 21, ESV', 'Jesus answered them, "Destroy this temple, and in three days I will raise it up."... But he was speaking about the temple of his body.', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 2), '0008-unit-1-recap-the-word-made-flesh.html', 8, 'The Word Made Flesh', 'Unit 1 Recap: The Word Made Flesh', 25, 'John 1:14, ESV', 'And the Word became flesh and dwelt among us, and we have seen his glory, glory as of the only Son from the Father, full of grace and truth.', 4),
  ('john', (select id from public.units where course_id = 'john' and position = 3), '0009-john-3-1-15-born-again.html', 9, 'You Must Be Born Again', 'John 3:1-15', 25, 'John 3:3, ESV', 'Jesus answered him, "Truly, truly, I say to you, unless one is born again he cannot see the kingdom of God."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 3), '0010-john-3-16-21-god-so-loved.html', 10, 'God So Loved the World', 'John 3:16-21', 25, 'John 3:16, ESV', 'For God so loved the world, that he gave his only Son, that whoever believes in him should not perish but have eternal life.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 3), '0011-john-3-22-36-he-must-increase.html', 11, 'He Must Increase', 'John 3:22-36', 25, 'John 3:29-30, ESV', 'The one who has the bride is the bridegroom. The friend of the bridegroom, who stands and hears him, rejoices greatly at the bridegroom''s voice. Therefore this joy of mine is now complete. He must increase, but I must decrease.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 3), '0012-john-4-1-26-living-water.html', 12, 'Living Water', 'John 4:1-26', 30, 'John 4:14, ESV', 'Whoever drinks of the water that I will give him will never be thirsty again. The water that I will give him will become in him a spring of water welling up to eternal life.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 3), '0013-john-4-27-45-the-harvest.html', 13, 'The Harvest', 'John 4:27-45', 25, 'John 4:28-29, ESV', 'So the woman left her water jar and went away into town and said to the people, "Come, see a man who told me all that I ever did. Can this be the Christ?"', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 3), '0014-john-4-46-54-the-second-sign.html', 14, 'The Second Sign', 'John 4:46-54', 25, 'John 4:48, ESV', 'So Jesus said to him, "Unless you see signs and wonders you will not believe."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 3), '0015-unit-2-recap-new-birth-and-living-water.html', 15, 'New Birth and Living Water', 'Unit 2 Recap: New Birth and Living Water', 25, 'John 3:16, ESV', 'For God so loved the world, that he gave his only Son, that whoever believes in him should not perish but have eternal life.', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 4), '0016-john-5-1-18-the-invalid-at-bethesda.html', 16, 'The Invalid at Bethesda', 'John 5:1-18', 25, 'John 5:17-18, ESV', 'But Jesus answered them, "My Father is working until now, and I am working." This was why the Jews were seeking all the more to kill him, because not only was he breaking the Sabbath, but he was even calling God his own Father, making himself equal with God.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 4), '0017-john-5-19-29-the-son-gives-life.html', 17, 'The Son Gives Life', 'John 5:19-29', 25, 'John 5:19, ESV', 'So Jesus said to them, "Truly, truly, I say to you, the Son can do nothing of his own accord, but only what he sees the Father doing. For whatever the Father does, that the Son does likewise."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 4), '0018-john-5-30-47-the-four-witnesses.html', 18, 'The Four Witnesses', 'John 5:30-47', 25, 'John 5:39-40, ESV', 'You search the Scriptures because you think that in them you have eternal life; and it is they that bear witness about me, yet you refuse to come to me that you may have life.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 4), '0019-john-6-1-21-bread-and-the-sea.html', 19, 'Bread and the Sea', 'John 6:1-21', 25, 'John 6:20, ESV', 'But he said to them, "It is I; do not be afraid."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 4), '0020-john-6-22-40-the-bread-of-life.html', 20, 'The Bread of Life', 'John 6:22-40', 30, 'John 6:29, ESV', 'Jesus answered them, "This is the work of God, that you believe in him whom he has sent."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 4), '0021-john-6-41-59-drawn-by-the-father.html', 21, 'Drawn by the Father', 'John 6:41-59', 30, 'John 6:44, ESV', 'No one can come to me unless the Father who sent me draws him. And I will raise him up on the last day.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 4), '0022-john-6-60-71-to-whom-shall-we-go.html', 22, 'To Whom Shall We Go', 'John 6:60-71', 25, 'John 6:63, ESV', 'It is the Spirit who gives life; the flesh is no help at all. The words that I have spoken to you are spirit and life.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 4), '0023-unit-3-recap-authority-and-bread.html', 23, 'Authority and Bread', 'Unit 3 Recap: Authority and Bread', 25, 'John 6:35, ESV', 'I am the bread of life; whoever comes to me shall not hunger, and whoever believes in me shall never thirst.', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 5), '0024-john-7-1-24-the-feast-of-booths.html', 24, 'The Feast of Booths', 'John 7:1-24', 25, 'John 7:6, ESV', 'Jesus said to them, "My time has not yet come, but your time is always here."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 5), '0025-john-7-25-52-rivers-of-living-water.html', 25, 'Rivers of Living Water', 'John 7:25-52', 30, 'John 7:37-38, ESV', 'If anyone thirsts, let him come to me and drink. Whoever believes in me, as the Scripture has said, "Out of his heart will flow rivers of living water."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 5), '0026-john-7-53-8-11-the-woman-caught.html', 26, 'The Woman Caught', 'John 7:53-8:11', 30, 'John 8:11, ESV', 'Neither do I condemn you; go, and from now on sin no more.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 5), '0027-john-8-12-30-the-light-of-the-world.html', 27, 'The Light of the World', 'John 8:12-30', 25, 'John 8:12, ESV', 'Again Jesus spoke to them, saying, "I am the light of the world. Whoever follows me will not walk in darkness, but will have the light of life."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 5), '0028-john-8-31-47-the-truth-will-set-you-free.html', 28, 'The Truth Will Set You Free', 'John 8:31-47', 25, 'John 8:31-32, ESV', 'If you abide in my word, you are truly my disciples, and you will know the truth, and the truth will set you free.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 5), '0029-john-8-48-59-before-abraham-was-i-am.html', 29, 'Before Abraham Was, I Am', 'John 8:48-59', 25, 'John 8:58, ESV', 'Jesus said to them, "Truly, truly, I say to you, before Abraham was, I am."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 5), '0030-unit-4-recap-light-in-conflict.html', 30, 'Light in Conflict', 'Unit 4 Recap: Light in Conflict', 25, 'John 8:12, ESV', 'I am the light of the world. Whoever follows me will not walk in darkness, but will have the light of life.', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 6), '0031-john-9-1-12-a-man-born-blind.html', 31, 'A Man Born Blind', 'John 9:1-12', 25, 'John 9:3, ESV', 'Jesus answered, "It was not that this man sinned, or his parents, but that the works of God might be displayed in him."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 6), '0032-john-9-13-41-the-trial-of-sight.html', 32, 'The Trial of Sight', 'John 9:13-41', 30, 'John 9:25, ESV', 'He answered, "Whether he is a sinner I do not know. One thing I know, that though I was blind, now I see."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 6), '0033-john-10-1-21-the-good-shepherd.html', 33, 'The Good Shepherd', 'John 10:1-21', 30, 'John 10:11, ESV', 'I am the good shepherd. The good shepherd lays down his life for the sheep.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 6), '0034-john-10-22-42-i-and-the-father-are-one.html', 34, 'I and the Father Are One', 'John 10:22-42', 25, 'John 10:30, ESV', 'I and the Father are one.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 6), '0035-unit-5-recap-the-shepherd-gives-sight.html', 35, 'The Shepherd Gives Sight', 'Unit 5 Recap: The Shepherd Gives Sight', 25, 'John 10:27-28, ESV', 'My sheep hear my voice, and I know them, and they follow me. I give them eternal life, and they will never perish, and no one will snatch them out of my hand.', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 7), '0036-john-11-1-16-this-illness-is-for-glory.html', 36, 'This Illness Is for Glory', 'John 11:1-16', 25, 'John 11:5-6, ESV', 'Now Jesus loved Martha and her sister and Lazarus. So, when he heard that Lazarus was ill, he stayed two days longer in the place where he was.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 7), '0037-john-11-17-44-the-resurrection-and-the-life.html', 37, 'The Resurrection and the Life', 'John 11:17-44', 30, 'John 11:25-26, ESV', 'Jesus said to her, "I am the resurrection and the life. Whoever believes in me, though he die, yet shall he live, and everyone who lives and believes in me shall never die. Do you believe this?"', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 7), '0038-john-11-45-57-one-man-for-the-people.html', 38, 'One Man for the People', 'John 11:45-57', 25, 'John 11:51-52, ESV', 'He did not say this of his own accord, but being high priest that year he prophesied that Jesus would die for the nation, and not for the nation only, but also to gather into one the children of God who are scattered abroad.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 7), '0039-john-12-1-19-the-anointing-and-the-entry.html', 39, 'The Anointing and the Entry', 'John 12:1-19', 25, 'John 12:7-8, ESV', 'Jesus said, "Leave her alone, so that she may keep it for the day of my burial. For the poor you always have with you, but you do not always have me."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 7), '0040-john-12-20-36-the-grain-of-wheat.html', 40, 'The Grain of Wheat', 'John 12:20-36', 25, 'John 12:24, ESV', 'Truly, truly, I say to you, unless a grain of wheat falls into the earth and dies, it remains alone; but if it dies, it bears much fruit.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 7), '0041-john-12-37-50-who-has-believed.html', 41, 'Who Has Believed', 'John 12:37-50', 25, 'John 12:39-40, ESV', 'Therefore they could not believe. For again Isaiah said, "He has blinded their eyes and hardened their heart, lest they see with their eyes, and understand with their heart, and turn, and I would heal them."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 7), '0042-unit-6-recap-the-resurrection-and-the-hour.html', 42, 'The Resurrection and the Hour', 'Unit 6 Recap: The Resurrection and the Hour', 30, 'John 11:25-26, ESV', 'I am the resurrection and the life. Whoever believes in me, though he die, yet shall he live, and everyone who lives and believes in me shall never die.', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 8), '0043-john-13-1-17-the-basin-and-the-towel.html', 43, 'The Basin and the Towel', 'John 13:1-17', 25, 'John 13:3-4, ESV', 'Jesus, knowing that the Father had given all things into his hands, and that he had come from God and was going back to God, rose from supper.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 8), '0044-john-13-18-38-a-new-commandment.html', 44, 'A New Commandment', 'John 13:18-38', 25, 'John 13:34, ESV', 'A new commandment I give to you, that you love one another: just as I have loved you, you also are to love one another.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 8), '0045-john-14-1-14-the-way-the-truth-the-life.html', 45, 'The Way, the Truth, the Life', 'John 14:1-14', 25, 'John 14:6, ESV', 'Jesus said to him, "I am the way, and the truth, and the life. No one comes to the Father except through me."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 8), '0046-john-14-15-31-another-helper.html', 46, 'Another Helper', 'John 14:15-31', 25, 'John 14:16-17, ESV', 'And I will ask the Father, and he will give you another Helper, to be with you forever, even the Spirit of truth.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 8), '0047-john-15-1-17-the-vine-and-the-branches.html', 47, 'The Vine and the Branches', 'John 15:1-17', 30, 'John 15:5, ESV', 'I am the vine; you are the branches. Whoever abides in me and I in him, he it is that bears much fruit, for apart from me you can do nothing.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 8), '0048-john-15-18-16-4-if-the-world-hates-you.html', 48, 'If the World Hates You', 'John 15:18-16:4', 25, 'John 15:19, ESV', 'If you were of the world, the world would love you as its own; but because you are not of the world, but I chose you out of the world, therefore the world hates you.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 8), '0049-john-16-5-33-sorrow-into-joy.html', 49, 'Sorrow into Joy', 'John 16:5-33', 30, 'John 16:7, ESV', 'Nevertheless, I tell you the truth: it is to your advantage that I go away, for if I do not go away, the Helper will not come to you. But if I go, I will send him to you.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 8), '0050-john-17-the-high-priestly-prayer.html', 50, 'The High Priestly Prayer', 'John 17:1-26', 30, 'John 17:6, ESV', 'I have manifested your name to the people whom you gave me out of the world. Yours they were, and you gave them to me, and they have kept your word.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 8), '0051-unit-7-recap-the-upper-room.html', 51, 'The Upper Room', 'Unit 7 Recap: The Upper Room', 30, 'John 16:33, ESV', 'I have said these things to you, that in me you may have peace. In the world you will have tribulation. But take heart; I have overcome the world.', 5),
  ('john', (select id from public.units where course_id = 'john' and position = 9), '0052-john-18-1-27-the-arrest-and-the-denials.html', 52, 'The Arrest and the Denials', 'John 18:1-27', 25, 'John 18:4, 6, ESV', 'Jesus, knowing all that would happen to him, came forward and said to them, "Whom do you seek?"... When Jesus said to them, "I am he," they drew back and fell to the ground.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 9), '0053-john-18-28-19-16-what-is-truth.html', 53, 'What Is Truth', 'John 18:28-19:16', 30, 'John 18:36, ESV', 'Jesus answered, "My kingdom is not of this world. If my kingdom were of this world, my servants would have been fighting, that I might not be delivered over to the Jews. But my kingdom is not from the world."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 9), '0054-john-19-17-30-it-is-finished.html', 54, 'It Is Finished', 'John 19:17-30', 30, 'John 19:30, ESV', 'When Jesus had received the sour wine, he said, "It is finished," and he bowed his head and gave up his spirit.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 9), '0055-john-19-31-42-pierced-and-buried.html', 55, 'Pierced and Buried', 'John 19:31-42', 25, 'John 19:36-37, ESV', 'For these things took place that the Scripture might be fulfilled: "Not one of his bones will be broken." And again another Scripture says, "They will look on him whom they have pierced."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 9), '0056-john-20-1-18-the-empty-tomb.html', 56, 'The Empty Tomb', 'John 20:1-18', 25, 'John 20:8, ESV', 'Then the other disciple, who had reached the tomb first, also went in, and he saw and believed.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 9), '0057-john-20-19-31-my-lord-and-my-god.html', 57, 'My Lord and My God', 'John 20:19-31', 30, 'John 20:28, ESV', 'Thomas answered him, "My Lord and my God!"', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 9), '0058-john-21-1-14-breakfast-by-the-sea.html', 58, 'Breakfast by the Sea', 'John 21:1-14', 25, 'John 21:11, ESV', 'So Simon Peter went aboard and hauled the net ashore, full of large fish, 153 of them. And although there were so many, the net was not torn.', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 9), '0059-john-21-15-25-do-you-love-me.html', 59, 'Do You Love Me', 'John 21:15-25', 25, 'John 21:17, ESV', 'He said to him the third time, "Simon, son of John, do you love me?" Peter was grieved because he said to him the third time, "Do you love me?" and he said to him, "Lord, you know everything; you know that I love you."', 6),
  ('john', (select id from public.units where course_id = 'john' and position = 10), '0060-course-capstone-that-you-may-believe.html', 60, 'That You May Believe', 'Capstone: That You May Believe', 40, 'John 20:31, ESV', 'But these are written so that you may believe that Jesus is the Christ, the Son of God, and that by believing you may have life in his name.', 6)
