  ('isaiah', 'Unit 7: Chapters 40-48', 8)
insert into public.lessons (course_id, unit_id, slug, n, title, reference, minutes, verse_ref, verse_text, quiz_count) values
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 1), '0001-how-to-study-scripture.html', 1, 'How to Study Scripture', '', 25, 'Isaiah 1:2-3, ESV', 'Hear, O heavens, and give ear, O earth; for the LORD has spoken: "Children have I reared and brought up, but they have rebelled against me. The ox knows its owner, and the donkey its master''s crib, but Israel does not know, my people do not understand."', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 1), '0002-isaiah-big-picture.html', 2, 'The Big Picture of Isaiah', '', 25, '', '', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 2), '0003-isaiah-1-1-20-the-lawsuit.html', 3, 'The Lawsuit', 'Isaiah 1:1-20', 30, 'Isaiah 1:18, ESV', '"Come now, let us reason together, says the LORD: though your sins are like scarlet, they shall be as white as snow; though they are red like crimson, they shall become like wool."', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 2), '0004-isaiah-1-21-31-the-faithful-city.html', 4, 'The Faithful City', 'Isaiah 1:21-31', 25, 'Isaiah 1:25-26, ESV', '"I will turn my hand against you and will smelt away your dross as with lye and remove all your alloy. And I will restore your judges as at the first... Afterward you shall be called the city of righteousness, the faithful city."', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 2), '0005-isaiah-2-1-5-the-mountain-of-the-lord.html', 5, 'Mountain of the LORD', 'Isaiah 2:1-5', 30, 'Isaiah 2:2, ESV', '"It shall come to pass in the latter days that the mountain of the house of the LORD shall be established as the highest of the mountains... and all the nations shall flow to it."', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 2), '0006-isaiah-2-6-22-the-day-against-pride.html', 6, 'Day Against Pride', 'Isaiah 2:6-22', 25, 'Isaiah 2:12, ESV', '"For the LORD of hosts has a day against all that is proud and lofty, against all that is lifted up; and it shall be brought low."', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 2), '0007-isaiah-3-1-4-1-judgment-on-leaders.html', 7, 'Judgment on Leaders', 'Isaiah 3:1-4:1', 30, 'Isaiah 3:14-15, ESV', '"The LORD will enter into judgment with the elders and princes of his people: ''It is you who have devoured the vineyard, the spoil of the poor is in your houses. What do you mean by crushing my people, by grinding the face of the poor?''"', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 2), '0008-isaiah-4-2-6-the-branch-of-the-lord.html', 8, 'The Branch', 'Isaiah 4:2-6', 25, 'Isaiah 4:2, ESV', 'In that day the branch of the LORD shall be beautiful and glorious, and the fruit of the land shall be the pride and honor of the survivors of Israel.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 2), '0009-isaiah-5-1-7-the-vineyard-song.html', 9, 'The Vineyard Song', 'Isaiah 5:1-7', 25, 'Isaiah 5:7, ESV', '...and he looked for justice, but behold, bloodshed; for righteousness, but behold, an outcry!', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 2), '0010-isaiah-5-8-30-six-woes.html', 10, 'Six Woes', 'Isaiah 5:8-30', 30, 'Isaiah 5:20, ESV', 'Woe to those who call evil good and good evil, who put darkness for light and light for darkness, who put bitter for sweet and sweet for bitter!', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 2), '0011-isaiah-6-1-7-holy-holy-holy.html', 11, 'Holy, Holy, Holy', 'Isaiah 6:1-7', 30, 'Isaiah 6:3, ESV', 'And one called to another and said: "Holy, holy, holy is the LORD of hosts; the whole earth is full of his glory!"', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 2), '0012-isaiah-6-8-13-the-commission.html', 12, 'The Commission', 'Isaiah 6:8-13', 30, '', '', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 3), '0013-isaiah-7-1-9-stand-firm-in-faith.html', 13, 'Firm in Faith', 'Isaiah 7:1-9', 30, 'Isaiah 7:9b, ESV', '"If you are not firm in faith, you will not be firm at all."', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 3), '0014-isaiah-7-10-25-the-immanuel-sign.html', 14, 'The Immanuel Sign', 'Isaiah 7:10-25', 30, 'Isaiah 7:14, ESV', '"Therefore the Lord himself will give you a sign. Behold, the virgin shall conceive and bear a son, and shall call his name Immanuel."', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 3), '0015-isaiah-8-1-22-the-stone-of-stumbling.html', 15, 'Stone of Stumbling', 'Isaiah 8:1-22', 30, 'Isaiah 8:13-14, ESV', '"But the LORD of hosts, him you shall honor as holy. Let him be your fear, and let him be your dread. And he will become a sanctuary and a stone of offense and a rock of stumbling..."', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 3), '0016-isaiah-9-1-7-unto-us-a-child.html', 16, 'Unto Us a Child', 'Isaiah 9:1-7', 30, 'Isaiah 9:7, ESV', 'Of the increase of his government and of peace there will be no end, on the throne of David and over his kingdom, to establish it and to uphold it with justice and with righteousness from this time forth and forevermore.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 3), '0017-isaiah-9-8-10-4-the-outstretched-hand.html', 17, 'Outstretched Hand', 'Isaiah 9:8-10:4', 25, 'Isaiah 9:12, ESV (also 9:17, 9:21, 10:4)', 'For all this his anger has not turned away, and his hand is stretched out still.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 3), '0018-isaiah-10-5-19-assyria-the-axe.html', 18, 'Assyria the Axe', 'Isaiah 10:5-19', 30, 'Isaiah 10:17, ESV', 'The light of Israel will become a fire, and his Holy One a flame, and it will burn and devour his thorns and briers in one day.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 3), '0019-isaiah-10-20-34-a-remnant-will-return.html', 19, 'A Remnant Returns', 'Isaiah 10:20-34', 30, 'Isaiah 10:22, ESV', 'For though your people Israel be as the sand of the sea, only a remnant of them will return. Destruction is decreed, overflowing with righteousness.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 3), '0020-isaiah-11-1-10-the-shoot-from-the-stump.html', 20, 'Shoot from the Stump', 'Isaiah 11:1-10', 30, 'Isaiah 11:9, ESV', 'They shall not hurt or destroy in all my holy mountain; for the earth shall be full of the knowledge of the LORD as the waters cover the sea.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 3), '0021-isaiah-11-11-16-the-second-exodus.html', 21, 'The Second Exodus', 'Isaiah 11:11-16', 30, 'Isaiah 11:16, ESV', 'And there will be a highway from Assyria for the remnant that remains of his people, as there was for Israel when they came up from the land of Egypt.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 3), '0022-isaiah-12-1-6-the-wells-of-salvation.html', 22, 'Wells of Salvation', 'Isaiah 12:1-6', 25, 'Isaiah 12:1, ESV', 'You will say in that day: "I will give thanks to you, O LORD, for though you were angry with me, your anger turned away, that you might comfort me."', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 4), '0023-isaiah-13-1-22-the-oracle-against-babylon.html', 23, 'Oracle: Babylon', 'Isaiah 13:1-22', 30, 'Isaiah 13:10, ESV', 'For the stars of the heavens and their constellations will not give their light; the sun will be dark at its rising, and the moon will not shed its light.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 4), '0024-isaiah-14-1-23-the-fall-of-the-tyrant.html', 24, 'Fall of the Tyrant', 'Isaiah 14:1-23', 30, 'Isaiah 14:12, ESV', 'How you are fallen from heaven, O Day Star, son of Dawn! How you are cut down to the ground, you who laid the nations low!', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 4), '0025-isaiah-14-24-32-assyria-broken-philistia-warned.html', 25, 'Assyria and Philistia', 'Isaiah 14:24-32', 30, 'Isaiah 14:27, ESV', 'For the LORD of hosts has purposed, and who will annul it? His hand is stretched out, and who will turn it back?', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 4), '0026-isaiah-15-1-16-14-the-oracle-against-moab.html', 26, 'Oracle: Moab', 'Isaiah 15:1-16:14', 30, 'Isaiah 15:5, ESV', 'My heart cries out for Moab; her fugitives flee to Zoar, to Eglath-shelishiyah.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 4), '0027-isaiah-17-18-damascus-and-cush.html', 27, 'Damascus and Cush', 'Isaiah 17:1-18:7', 30, 'Isaiah 17:6, ESV', 'Gleanings will be left in it, as when an olive tree is beaten: two or three berries in the top of the highest bough.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 4), '0028-isaiah-19-1-15-egypt-undone.html', 28, 'Egypt Undone', 'Isaiah 19:1-15', 25, 'Isaiah 19:3, ESV', 'And the spirit of the Egyptians within them will be emptied out, and I will confound their counsel.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 4), '0029-isaiah-19-16-20-6-egypt-my-people.html', 29, 'Egypt My People', 'Isaiah 19:16-20:6', 30, 'Isaiah 19:22, ESV', 'And the LORD will strike Egypt, striking and healing, and they will return to the LORD, and he will listen to their pleas for mercy and heal them.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 4), '0030-isaiah-21-fallen-fallen-is-babylon.html', 30, 'Fallen Is Babylon', 'Isaiah 21:1-17', 25, 'Isaiah 21:9, ESV', 'Fallen, fallen is Babylon; and all the carved images of her gods he has shattered to the ground.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 4), '0031-isaiah-22-the-valley-of-vision.html', 31, 'The Valley of Vision', 'Isaiah 22:1-25', 30, 'Isaiah 22:11, ESV', 'You made a reservoir between the two walls for the water of the old pool. But you did not look to him who did it, or see him who planned it long ago.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 4), '0032-isaiah-23-the-oracle-against-tyre.html', 32, 'Oracle: Tyre', 'Isaiah 23:1-18', 30, 'Isaiah 23:18, ESV', 'Her merchandise and her wages will be holy to the LORD. It will not be stored or hoarded, but her merchandise will supply abundant food and fine clothing for those who dwell before the LORD.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 5), '0033-isaiah-24-the-earth-laid-waste.html', 33, 'Earth Laid Waste', 'Isaiah 24:1-23', 30, 'Isaiah 24:5, ESV', 'The earth lies defiled under its inhabitants; for they have transgressed the laws, violated the statutes, broken the everlasting covenant.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 5), '0034-isaiah-25-the-feast-on-the-mountain.html', 34, 'Feast on the Mountain', 'Isaiah 25:1-12', 30, 'Isaiah 25:6, ESV', 'On this mountain the LORD of hosts will make for all peoples a feast of rich food, a feast of well-aged wine, of rich food full of marrow, of aged wine well refined.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 5), '0035-isaiah-26-perfect-peace.html', 35, 'Perfect Peace', 'Isaiah 26:1-21', 30, 'Isaiah 26:3, ESV', 'You keep him in perfect peace whose mind is stayed on you, because he trusts in you.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 5), '0036-isaiah-27-the-vineyard-sings-again.html', 36, 'Vineyard Sings Again', 'Isaiah 27:1-13', 30, 'Isaiah 27:1, ESV', 'In that day the LORD with his hard and great and strong sword will punish Leviathan the fleeing serpent, Leviathan the twisting serpent, and he will slay the dragon that is in the sea.', 5),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 6), '0037-isaiah-28-the-cornerstone-in-zion.html', 37, 'Cornerstone in Zion', 'Isaiah 28:1-29', 30, 'Isaiah 28:16, ESV', 'Behold, I am the one who has laid as a foundation in Zion, a stone, a tested stone, a precious cornerstone, of a sure foundation: "Whoever believes will not be in haste."', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 6), '0038-isaiah-29-1-14-ariel-and-the-sealed-book.html', 38, 'Ariel, Sealed Book', 'Isaiah 29:1-14', 25, 'Isaiah 29:13, ESV', 'Because this people draw near with their mouth and honor me with their lips, while their hearts are far from me, and their fear of me is a commandment taught by men...', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 6), '0039-isaiah-29-15-24-the-potter-and-the-clay.html', 39, 'Potter and Clay', 'Isaiah 29:15-24', 25, 'Isaiah 29:16, ESV', 'You turn things upside down! Shall the potter be regarded as the clay, that the thing made should say of its maker, "He did not make me"; or the thing formed say of him who formed it, "He has no understanding"?', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 6), '0040-isaiah-30-1-17-in-returning-and-rest.html', 40, 'Returning and Rest', 'Isaiah 30:1-17', 30, 'Isaiah 30:15, ESV', 'For thus said the Lord GOD, the Holy One of Israel, "In returning and rest you shall be saved; in quietness and in trust shall be your strength." But you were unwilling.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 6), '0041-isaiah-30-18-33-the-lord-waits-to-be-gracious.html', 41, 'He Waits to Be Gracious', 'Isaiah 30:18-33', 25, 'Isaiah 30:18, ESV', 'Therefore the LORD waits to be gracious to you, and therefore he exalts himself to show mercy to you. For the LORD is a God of justice; blessed are all those who wait for him.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 6), '0042-isaiah-31-woe-to-those-who-go-down-to-egypt.html', 42, 'Down to Egypt', 'Isaiah 31:1-9', 25, 'Isaiah 31:3, ESV', 'The Egyptians are man, and not God, and their horses are flesh, and not spirit. When the LORD stretches out his hand, the helper will stumble, and he who is helped will fall, and they will all perish together.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 6), '0043-isaiah-32-a-king-in-righteousness.html', 43, 'King in Righteousness', 'Isaiah 32:1-20', 30, 'Isaiah 32:1-2, ESV', 'Behold, a king will reign in righteousness, and princes will rule in justice. Each will be like a hiding place from the wind, a shelter from the storm, like streams of water in a dry place, like the shade of a great rock in a weary land.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 6), '0044-isaiah-33-the-king-in-his-beauty.html', 44, 'King in His Beauty', 'Isaiah 33:1-24', 30, 'Isaiah 33:17, ESV', 'Your eyes will behold the king in his beauty; they will see a land that stretches afar.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 6), '0045-isaiah-34-the-day-of-vengeance.html', 45, 'Day of Vengeance', 'Isaiah 34:1-17', 25, 'Isaiah 34:8, ESV', 'For the LORD has a day of vengeance, a year of recompense for the cause of Zion.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 6), '0046-isaiah-35-the-desert-blooms.html', 46, 'Desert Blooms', 'Isaiah 35:1-10', 30, 'Isaiah 35:3-4, ESV', 'Strengthen the weak hands, and make firm the feeble knees. Say to those who have an anxious heart, "Be strong; fear not! Behold, your God will come with vengeance, with the recompense of God. He will come and save you."', 5),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 7), '0047-isaiah-36-the-rabshakeh-at-the-wall.html', 47, 'Rabshakeh at the Wall', 'Isaiah 36:1-22', 30, 'Isaiah 36:4-5, ESV', 'Say to Hezekiah, "Thus says the great king, the king of Assyria: On what do you rest this trust of yours?... In whom do you now trust, that you have rebelled against me?"', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 7), '0048-isaiah-37-the-angel-and-the-answer.html', 48, 'Angel and the Answer', 'Isaiah 37:1-38', 30, 'Isaiah 37:14, ESV', 'Hezekiah received the letter from the hand of the messengers, and read it; and Hezekiah went up to the house of the LORD, and spread it before the LORD.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 7), '0049-isaiah-38-hezekiahs-fifteen-years.html', 49, 'Hezekiah''s Fifteen Years', 'Isaiah 38:1-22', 25, 'Isaiah 38:17, ESV', 'Behold, it was for my welfare that I had great bitterness; but in love you have delivered my life from the pit of destruction, for you have cast all my sins behind your back.', 4),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 7), '0050-isaiah-39-the-envoys-from-babylon.html', 50, 'Envoys from Babylon', 'Isaiah 39:1-8', 25, '2 Chronicles 32:31, ESV', 'And so in the matter of the envoys of the princes of Babylon, who had been sent to him to inquire about the sign that had been done in the land, God left him to himself, in order to test him and to know all that was in his heart.', 5),
  ('isaiah', (select id from public.units where course_id = 'isaiah' and position = 8), '0051-isaiah-40-1-11-comfort-my-people.html', 51, 'Comfort My People', 'Isaiah 40:1-11', 30, 'Isaiah 40:3, ESV', 'A voice cries: "In the wilderness prepare the way of the LORD; make straight in the desert a highway for our God."', 4)
