insert into public.lessons (course_id, unit_id, slug, n, title, reference, minutes, verse_ref, verse_text, quiz_count) values
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 1), '0001-how-to-study-a-doctrine.html', 1, 'How to Study a Doctrine', '2 Timothy 2:15; Acts 17:10-12', 25, 'Acts 17:11, ESV', 'Now these Jews were more noble than those in Thessalonica; they received the word with all eagerness, examining the Scriptures daily to see if these things were so.', 5),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 1), '0002-trinity-big-picture.html', 2, 'The Big Picture of the Trinity', 'Deuteronomy 6:4; Matthew 28:19; 2 Corinthians 13:14', 25, '', '', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 2), '0003-deuteronomy-6-4-9-the-shema.html', 3, 'The LORD Is One', 'Deuteronomy 6:4-9', 25, 'Deuteronomy 6:4, ESV', '"Hear, O Israel: The LORD our God, the LORD is one."', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 2), '0004-isaiah-45-no-god-besides-me.html', 4, 'No God Besides Me', 'Isaiah 44:6-8; 45:5-7, 21-23', 25, 'Isaiah 44:6, ESV', 'Thus says the LORD, the King of Israel and his Redeemer, the LORD of hosts: "I am the first and I am the last; besides me there is no god."', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 2), '0005-genesis-1-let-us-make-man.html', 5, 'Let Us Make Man', 'Genesis 1:1-3, 26-28', 25, 'Genesis 1:26, ESV', 'Then God said, "Let us make man in our image, after our likeness."', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 2), '0006-unit-1-recap-one-god.html', 6, 'One God', 'Unit 1 Recap: One God', 25, 'Deuteronomy 6:4, ESV', '"Hear, O Israel: The LORD our God, the LORD is one."', 4),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 3), '0007-john-1-1-18-the-word-was-god.html', 7, 'The Word Was God', 'John 1:1-18', 25, 'John 1:1, ESV', 'In the beginning was the Word, and the Word was with God, and the Word was God.', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 3), '0008-john-5-16-30-equal-with-god.html', 8, 'Equal with God', 'John 5:16-30', 25, 'John 5:18, ESV', 'This was why the Jews were seeking all the more to kill him, because not only was he breaking the Sabbath, but he was even calling God his own Father, making himself equal with God.', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 3), '0009-philippians-2-5-11-the-form-of-god.html', 9, 'The Form of God', 'Philippians 2:5-11', 25, 'Philippians 2:6-7, ESV', '...who, though he was in the form of God, did not count equality with God a thing to be grasped, but emptied himself, by taking the form of a servant, being born in the likeness of men.', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 3), '0010-colossians-1-15-20-the-image-of-the-invisible-god.html', 10, 'Image of the Invisible God', 'Colossians 1:15-20', 25, 'Colossians 1:15-16, ESV', 'He is the image of the invisible God, the firstborn of all creation. For by him all things were created, in heaven and on earth, visible and invisible...', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 3), '0011-hebrews-1-the-radiance-of-his-glory.html', 11, 'The Radiance of His Glory', 'Hebrews 1', 25, 'Hebrews 1:3, ESV', 'He is the radiance of the glory of God and the exact imprint of his nature, and he upholds the universe by the word of his power.', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 3), '0012-unit-2-recap-the-son-is-god.html', 12, 'The Son Is God', 'Unit 2 Recap: The Son Is God', 25, 'John 1:1, ESV', 'In the beginning was the Word, and the Word was with God, and the Word was God.', 4),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 4), '0013-john-14-15-31-another-helper.html', 13, 'Another Helper', 'John 14:15-31', 25, 'John 14:16-17, ESV', '"And I will ask the Father, and he will give you another Helper, to be with you forever, even the Spirit of truth..."', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 4), '0014-john-16-5-15-he-will-glorify-me.html', 14, 'He Will Glorify Me', 'John 16:5-15', 25, 'John 16:7, ESV', '"Nevertheless, I tell you the truth: it is to your advantage that I go away, for if I do not go away, the Helper will not come to you. But if I go, I will send him to you."', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 4), '0015-acts-5-1-11-lying-to-the-holy-spirit.html', 15, 'Lying to the Holy Spirit', 'Acts 5:1-11', 25, 'Acts 5:3-4, ESV', 'But Peter said, "Ananias, why has Satan filled your heart to lie to the Holy Spirit...? You have not lied to man but to God."', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 4), '0016-1-corinthians-2-6-16-the-depths-of-god.html', 16, 'The Depths of God', '1 Corinthians 2:6-16', 25, '1 Corinthians 2:10-11, ESV', '...these things God has revealed to us through the Spirit. For the Spirit searches everything, even the depths of God. For who knows a person''s thoughts except the spirit of that person, which is in him? So also no one comprehends the thoughts of God except the Spirit of God.', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 4), '0017-unit-3-recap-the-spirit-is-god.html', 17, 'The Spirit Is God', 'Unit 3 Recap: The Spirit Is God', 25, 'John 14:26, ESV', '"But the Helper, the Holy Spirit, whom the Father will send in my name, he will teach you all things and bring to your remembrance all that I have said to you."', 4),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 5), '0018-matthew-3-13-17-the-baptism-of-jesus.html', 18, 'The Baptism of Jesus', 'Matthew 3:13-17', 25, 'Matthew 3:16-17, ESV', 'And when Jesus was baptized, immediately he went up from the water, and behold, the heavens were opened to him, and he saw the Spirit of God descending like a dove and coming to rest on him; and behold, a voice from heaven said, "This is my beloved Son, with whom I am well pleased."', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 5), '0019-matthew-28-16-20-one-name-three-persons.html', 19, 'One Name, Three Persons', 'Matthew 28:16-20', 25, 'Matthew 28:19, ESV', '"Go therefore and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit..."', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 5), '0020-ephesians-1-3-14-the-shape-of-salvation.html', 20, 'The Shape of Salvation', 'Ephesians 1:3-14', 25, 'Ephesians 1:13-14, ESV', 'In him you also, when you heard the word of truth, the gospel of your salvation, and believed in him, were sealed with the promised Holy Spirit, who is the guarantee of our inheritance until we acquire possession of it, to the praise of his glory.', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 5), '0021-unit-4-recap-three-persons-one-god.html', 21, 'Three Persons, One God', 'Unit 4 Recap: Three Persons, One God', 25, 'Matthew 28:19, ESV', '"Go therefore and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit."', 5),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 6), '0022-the-boundary-lines-heresies-and-creeds.html', 22, 'Heresies and Creeds', 'The Boundary Lines: Heresies and Creeds', 30, 'John 8:58-59, ESV', 'Jesus said to them, "Truly, truly, I say to you, before Abraham was, I am." So they picked up stones to throw at him...', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 6), '0023-ephesians-2-11-22-access-in-one-spirit.html', 23, 'Access in One Spirit', 'Ephesians 2:11-22', 25, 'Ephesians 2:18, ESV', 'For through him we both have access in one Spirit to the Father.', 6),
  ('trinity', (select id from public.units where course_id = 'trinity' and position = 7), '0024-course-capstone-the-grace-the-love-the-fellowship.html', 24, 'The Grace, the Love, the Fellowship', 'Capstone: The Grace, the Love, the Fellowship', 30, '2 Corinthians 13:14, ESV', 'The grace of the Lord Jesus Christ and the love of God and the fellowship of the Holy Spirit be with you all.', 5)
